import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor convtranspose3d_forward(torch::Tensor x,
                                      torch::Tensor w,
                                      c10::optional<torch::Tensor> b,
                                      int stride, int padding, int output_padding, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
__device__ __forceinline__ int floordiv_pos(int a, int b) {
  // b > 0
  int q = a / b;
  int r = a % b;
  if (r != 0 && a < 0) --q;
  return q;
}
template <typename T, int TILE_OH, int TILE_OW, int CcPerBlock>
__global__ void convtranspose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K, int stride, int padding, int groups,
    int OD, int OH, int OW,
    int group_size_in, int group_size_out,
    int IH_TILE, int IW_TILE, int oc_tiles)
{
  extern __shared__ float smem_raw[];
  const int tid = threadIdx.x;
  const int Threads = TILE_OH * TILE_OW;
  // Decode grid.z -> n, oc_tile, od
  int gz = blockIdx.z;
  const int od = gz % OD; gz /= OD;
  const int oc_tile = gz % oc_tiles; gz /= oc_tiles;
  const int n = gz;
  const int oc_base = oc_tile * CcPerBlock;
  const int oh0 = blockIdx.y * TILE_OH;
  const int ow0 = blockIdx.x * TILE_OW;
  const int local_oh = tid / TILE_OW;
  const int local_ow = tid % TILE_OW;
  const int oh = oh0 + local_oh;
  const int ow = ow0 + local_ow;
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * OD * OH * OW;
  const int64_t sYc = (int64_t)OD * OH * OW;
  const int64_t sYd = (int64_t)OH * OW;
  const int64_t sYh = (int64_t)OW;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, OD, OH, OW),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  const int64_t sWic  = (int64_t)group_size_out * K * K * K;
  const int64_t sWocl = (int64_t)K * K * K;
  const int64_t sWkd  = (int64_t)K * K;
  const int64_t sWkh  = (int64_t)K;
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, group_size_out, K, K, K),
      make_stride(sWic, sWocl, sWkd, sWkh, Int<1>{})
  );
  // Shared weight cache: (CcPerBlock, Cin, K, K, K)
  const int64_t sSic  = (int64_t)K * K * K;
  const int64_t sSkd  = (int64_t)K * K;
  const int64_t sSkh  = (int64_t)K;
  const int64_t sScc  = (int64_t)Cin * K * K * K;
  auto sW = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(CcPerBlock, Cin, K, K, K),
      make_stride(sScc, sSic, sSkd, sSkh, Int<1>{})
  );
  const int64_t weight_elems = (int64_t)CcPerBlock * Cin * K * K * K;
  float* sX_raw = smem_raw + weight_elems;
  // Shared input tile cache: (K, Cin, IH_TILE, IW_TILE)
  const int64_t sXsk  = (int64_t)Cin * IH_TILE * IW_TILE;
  const int64_t sXsc  = (int64_t)IH_TILE * IW_TILE;
  const int64_t sXsh  = (int64_t)IW_TILE;
  auto sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(K, Cin, IH_TILE, IW_TILE),
      make_stride(sXsk, sXsc, sXsh, Int<1>{})
  );
  // Cooperative load of weights + group masking into shared memory
  const int totalW = CcPerBlock * Cin * K * K * K;
  for (int idx = tid; idx < totalW; idx += Threads) {
    int tmp = idx;
    int kw = tmp % K; tmp /= K;
    int kh = tmp % K; tmp /= K;
    int kd = tmp % K; tmp /= K;
    int ic = tmp % Cin; tmp /= Cin;
    int cc = tmp;
    int oc = oc_base + cc;
    float val = 0.0f;
    if (oc < Cout) {
      int g = oc / group_size_out;
      int oc_local = oc % group_size_out;
      int ic_lo = g * group_size_in;
      int ic_hi = ic_lo + group_size_in;
      if (ic >= ic_lo && ic < ic_hi) {
        val = (float)mW(ic, oc_local, kd, kh, kw);
      }
    }
    sW(cc, ic, kd, kh, kw) = val;
  }
  // Compute bounding box base offsets for the input tile
  const int ih_min = floordiv_pos(oh0 + padding - (K - 1), stride);
  const int iw_min = floordiv_pos(ow0 + padding - (K - 1), stride);
  // Cooperative load of input tile into shared memory
  const int totalX = K * Cin * IH_TILE * IW_TILE;
  for (int idx = tid; idx < totalX; idx += Threads) {
    int tmp = idx;
    int iw_local = tmp % IW_TILE; tmp /= IW_TILE;
    int ih_local = tmp % IH_TILE; tmp /= IH_TILE;
    int ic = tmp % Cin; tmp /= Cin;
    int kd = tmp;
    int id_raw = od + padding - kd;
    bool valid = (id_raw % stride == 0);
    int id = id_raw / stride;
    valid = valid && (id >= 0) && (id < D);
    int ih = ih_min + ih_local;
    int iw = iw_min + iw_local;
    valid = valid && (ih >= 0) && (ih < H) && (iw >= 0) && (iw < Win);
    float val = valid ? (float)mX(ic, id, ih, iw) : 0.0f;
    sX(kd, ic, ih_local, iw_local) = val;
  }
  __syncthreads();
  if (oh >= OH || ow >= OW) return;
  float acc[CcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_base + cc;
    acc[cc] = (Bp != nullptr && oc < Cout) ? (float)Bp[oc] : 0.0f;
  }
  for (int kd = 0; kd < K; ++kd) {
    int id_raw = od + padding - kd;
    if (id_raw % stride != 0) continue;
    int id = id_raw / stride;
    if ((unsigned)id >= (unsigned)D) continue;
    for (int kh = 0; kh < K; ++kh) {
      int ih_raw = oh + padding - kh;
      if (ih_raw % stride != 0) continue;
      int ih = ih_raw / stride;
      if ((unsigned)ih >= (unsigned)H) continue;
      int ih_local = ih - ih_min;
      if (ih_local < 0 || ih_local >= IH_TILE) continue;
      for (int kw = 0; kw < K; ++kw) {
        int iw_raw = ow + padding - kw;
        if (iw_raw % stride != 0) continue;
        int iw = iw_raw / stride;
        if ((unsigned)iw >= (unsigned)Win) continue;
        int iw_local = iw - iw_min;
        if (iw_local < 0 || iw_local >= IW_TILE) continue;
        for (int ic = 0; ic < Cin; ++ic) {
          float xval = sX(kd, ic, ih_local, iw_local);
          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            float wval = sW(cc, ic, kd, kh, kw);
            acc[cc] += xval * wval;
          }
        }
      }
    }
  }
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_base + cc;
    if (oc >= Cout) continue;
    mY(oc, od, oh, ow) = static_cast<T>(acc[cc]);
  }
}
torch::Tensor convtranspose3d_forward(torch::Tensor x,
                                      torch::Tensor w,
                                      c10::optional<torch::Tensor> b,
                                      int stride, int padding, int output_padding, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, K, K, K]");
  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);
  TORCH_CHECK(w.size(0) == Cin, "w.size(0) must equal Cin");
  int64_t group_size_out = w.size(1);
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
  int64_t Cout = group_size_out * groups;
  int64_t group_size_in = Cin / groups;
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  TORCH_CHECK(output_padding >= 0, "output_padding must be >= 0");
  int64_t OD = (D - 1) * stride - 2 * padding + K + output_padding;
  int64_t OH = (H - 1) * stride - 2 * padding + K + output_padding;
  int64_t OW = (Win - 1) * stride - 2 * padding + K + output_padding;
  TORCH_CHECK(OD > 0 && OH > 0 && OW > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, OD, OH, OW}, x.options());
  constexpr int TILE_OH = 4;
  constexpr int TILE_OW = 8;
  constexpr int CcPerBlock = 2;
  constexpr int Threads = TILE_OH * TILE_OW;
  const int IH_TILE = TILE_OH + (int)K - 1;
  const int IW_TILE = TILE_OW + (int)K - 1;
  const int OH_tiles = (int)((OH + TILE_OH - 1) / TILE_OH);
  const int OW_tiles = (int)((OW + TILE_OW - 1) / TILE_OW);
  const int oc_tiles = (int)((Cout + CcPerBlock - 1) / CcPerBlock);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)OW_tiles,
      (unsigned)OH_tiles,
      (unsigned)((int64_t)N * oc_tiles * OD)
  );
  size_t weight_shmem = (size_t)CcPerBlock * (size_t)Cin * (size_t)K * (size_t)K * (size_t)K * sizeof(float);
  size_t input_shmem  = (size_t)K * (size_t)Cin * (size_t)IH_TILE * (size_t)IW_TILE * sizeof(float);
  size_t shmem_bytes = weight_shmem + input_shmem;
  if (shmem_bytes > 48 * 1024) {
    auto attr_err = cudaFuncSetAttribute(
        convtranspose3d_kernel<float, TILE_OH, TILE_OW, CcPerBlock>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)shmem_bytes
    );
    TORCH_CHECK(attr_err == cudaSuccess, "Failed to opt-in to ", shmem_bytes, " bytes of dynamic shared memory: ", cudaGetErrorString(attr_err));
  }
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  convtranspose3d_kernel<float, TILE_OH, TILE_OW, CcPerBlock><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding, groups,
      (int)OD, (int)OH, (int)OW,
      (int)group_size_in, (int)group_size_out,
      IH_TILE, IW_TILE, oc_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convtranspose3d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

convtranspose3d_ext = load_inline(
    name="cute_convtranspose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["convtranspose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with square input and square kernel,
    implemented via a custom CUDA kernel using CuTe tensors.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        # Weight shape matches PyTorch ConvTranspose3d: (in_channels, out_channels/groups, K, K, K)
        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = convtranspose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * (self.kernel_size ** 3)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.convtranspose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.output_padding),
            int(self.groups),
        )

