  extern __shared__ float smem_raw[];
  const int tid = threadIdx.x;
  const int Threads = TILE_OH * TILE_OW;
  // Decode grid.z -> n, oc_tile, od
  int gz = blockIdx.z;
  const int od = gz % OD; gz /= OD;
  const int oc_tile = gz % oc_tiles; gz /= oc_tiles;
  const int n = gz;
  const int oc_base = oc_tile * CcPerBlock;
  const int oh0 = blockIdx.y * TILE_OH;
  const int ow0 = blockIdx.x * TILE_OW;
  const int local_oh = tid / TILE_OW;
  const int local_ow = tid % TILE_OW;
  const int oh = oh0 + local_oh;
  const int ow = ow0 + local_ow;
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * OD * OH * OW;
  const int64_t sYc = (int64_t)OD * OH * OW;
  const int64_t sYd = (int64_t)OH * OW;
  const int64_t sYh = (int64_t)OW;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, OD, OH, OW),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  const int64_t sWic  = (int64_t)group_size_out * K * K * K;
  const int64_t sWocl = (int64_t)K * K * K;
  const int64_t sWkd  = (int64_t)K * K;
  const int64_t sWkh  = (int64_t)K;
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, group_size_out, K, K, K),
      make_stride(sWic, sWocl, sWkd, sWkh, Int<1>{})
  );
  // Shared weight cache: (CcPerBlock, Cin, K, K, K)
  const int64_t sSic  = (int64_t)K * K * K;
  const int64_t sSkd  = (int64_t)K * K;
  const int64_t sSkh  = (int64_t)K;
  const int64_t sScc  = (int64_t)Cin * K * K * K;
  auto sW = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(CcPerBlock, Cin, K, K, K),
      make_stride(sScc, sSic, sSkd, sSkh, Int<1>{})
  );
  const int64_t weight_elems = (int64_t)CcPerBlock * Cin * K * K * K;
  float* sX_raw = smem_raw + weight_elems;
  // Shared input tile cache: (K, Cin, IH_TILE, IW_TILE)
  const int64_t sXsk  = (int64_t)Cin * IH_TILE * IW_TILE;
  const int64_t sXsc  = (int64_t)IH_TILE * IW_TILE;
  const int64_t sXsh  = (int64_t)IW_TILE;
  auto sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(K, Cin, IH_TILE, IW_TILE),
      make_stride(sXsk, sXsc, sXsh, Int<1>{})
  );
  // Cooperative load of weights + group masking into shared memory
  const int totalW = CcPerBlock * Cin * K * K * K;
  for (int idx = tid; idx < totalW; idx += Threads) {
    int tmp = idx;
    int kw = tmp % K; tmp /= K;
    int kh = tmp % K; tmp /= K;
    int kd = tmp % K; tmp /= K;
    int ic = tmp % Cin; tmp /= Cin;
    int cc = tmp;
    int oc = oc_base + cc;
    float val = 0.0f;
    if (oc < Cout) {
      int g = oc / group_size_out;
      int oc_local = oc % group_size_out;
      int ic_lo = g * group_size_in;
      int ic_hi = ic_lo + group_size_in;
      if (ic >= ic_lo && ic < ic_hi) {
        val = (float)mW(ic, oc_local, kd, kh, kw);
      }
    }
    sW(cc, ic, kd, kh, kw) = val;
  }
  // Compute bounding box base offsets for the input tile
  const int ih_min = floordiv_pos(oh0 + padding - (K - 1), stride);
  const int iw_min = floordiv_pos(ow0 + padding - (K - 1), stride);
  // Cooperative load of input tile into shared memory
  const int totalX = K * Cin * IH_TILE * IW_TILE;
  for (int idx = tid; idx < totalX; idx += Threads) {
    int tmp = idx;
    int iw_local = tmp % IW_TILE; tmp /= IW_TILE;
    int ih_local = tmp % IH_TILE; tmp /= IH_TILE;
    int ic = tmp % Cin; tmp /= Cin;
    int kd = tmp;
    int id_raw = od + padding - kd;
    bool valid = (id_raw % stride == 0);
    int id = id_raw / stride;
    valid = valid && (id >= 0) && (id < D);
    int ih = ih_min + ih_local;
    int iw = iw_min + iw_local;
    valid = valid && (ih >= 0) && (ih < H) && (iw >= 0) && (iw < Win);
    float val = valid ? (float)mX(ic, id, ih, iw) : 0.0f;
    sX(kd, ic, ih_local, iw_local) = val;
  }
  __syncthreads();
  if (oh >= OH || ow >= OW) return;
  float acc[CcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_base + cc;
    acc[cc] = (Bp != nullptr && oc < Cout) ? (float)Bp[oc] : 0.0f;
  }
  for (int kd = 0; kd < K; ++kd) {
    int id_raw = od + padding - kd;
    if (id_raw % stride != 0) continue;
    int id = id_raw / stride;
    if ((unsigned)id >= (unsigned)D) continue;
    for (int kh = 0; kh < K; ++kh) {
      int ih_raw = oh + padding - kh;
      if (ih_raw % stride != 0) continue;
      int ih = ih_raw / stride;
      if ((unsigned)ih >= (unsigned)H) continue;
      int ih_local = ih - ih_min;
      if (ih_local < 0 || ih_local >= IH_TILE) continue;
      for (int kw = 0; kw < K; ++kw) {
        int iw_raw = ow + padding - kw;
        if (iw_raw % stride != 0) continue;
        int iw = iw_raw / stride;
        if ((unsigned)iw >= (unsigned)Win) continue;
        int iw_local = iw - iw_min;
        if (iw_local < 0 || iw_local >= IW_TILE) continue;
        for (int ic = 0; ic < Cin; ++ic) {
          float xval = sX(kd, ic, ih_local, iw_local);
          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            float wval = sW(cc, ic, kd, kh, kw);
            acc[cc] += xval * wval;
          }
        }
      }
    }
  }
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_base + cc;
    if (oc >= Cout) continue;
    mY(oc, od, oh, ow) = static_cast<T>(acc[cc]);
  }
}
