  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  convtranspose3d_kernel<float, Threads, PVec, CcPerBlock><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding, groups,
      (int)OD, (int)OH, (int)OW,
      (int)group_size_in, (int)group_size_out
